--
-- Name: calculate_user_kpi_actual(uuid, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_user_kpi_actual(p_user_id uuid, p_kpi_key text, p_start date, p_end date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
