CREATE FUNCTION public.calculate_visit_completion_rate(p_user_id uuid, p_start date, p_end date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  planned_count INTEGER;
  completed_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO planned_count
  FROM public.visits
  WHERE user_id = p_user_id AND planned_date BETWEEN p_start AND p_end;
  
