--
-- Name: get_password_reset_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_password_reset_stats() RETURNS TABLE(email text, total_attempts bigint, failed_attempts bigint, is_locked boolean, last_attempt timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    pra.email,
    COUNT(*)::BIGINT as total_attempts,
    COUNT(*) FILTER (WHERE was_successful = false)::BIGINT as failed_attempts,
    public.is_account_locked(pra.email) as is_locked,
    MAX(pra.attempted_at) as last_attempt
  FROM public.password_reset_attempts pra
  WHERE pra.attempted_at > NOW() - INTERVAL '24 hours'
    AND public.has_role(auth.uid(), 'admin'::public.app_role)
  GROUP BY pra.email
  ORDER BY last_attempt DESC;
$$;


--
-- Name: get_product_revenue_performance(date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_product_revenue_performance(p_start_date date DEFAULT (CURRENT_DATE - '30 days'::interval), p_end_date date DEFAULT CURRENT_DATE, p_limit integer DEFAULT 10) RETURNS TABLE(product_id uuid, product_name text, total_quantity numeric, total_revenue numeric, order_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id as product_id,
    p.name as product_name,
    COALESCE(SUM(oi.quantity), 0) as total_quantity,
    COALESCE(SUM(oi.total_price), 0) as total_revenue,
    COUNT(DISTINCT oi.order_id) as order_count
  FROM products p
  LEFT JOIN order_items oi ON oi.product_id = p.id
  LEFT JOIN orders o ON o.id = oi.order_id AND o.order_date BETWEEN p_start_date AND p_end_date
  GROUP BY p.id, p.name
  ORDER BY total_revenue DESC
  LIMIT p_limit;
END;
$$;


--
-- Name: get_productivity_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_productivity_summary(p_user_id uuid DEFAULT NULL::uuid, p_start_date date DEFAULT (CURRENT_DATE - '30 days'::interval), p_end_date date DEFAULT CURRENT_DATE) RETURNS TABLE(user_id uuid, full_name text, total_visits bigint, productive_visits bigint, total_orders bigint, total_revenue numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id as user_id,
    p.full_name,
    COUNT(DISTINCT v.id) as total_visits,
    COUNT(DISTINCT CASE WHEN v.is_productive THEN v.id END) as productive_visits,
    COUNT(DISTINCT o.id) as total_orders,
    COALESCE(SUM(o.total_amount), 0) as total_revenue
  FROM profiles p
  LEFT JOIN visits v ON v.user_id = p.id AND v.visit_date BETWEEN p_start_date AND p_end_date
  LEFT JOIN orders o ON o.user_id = p.id AND o.order_date BETWEEN p_start_date AND p_end_date
  WHERE (p_user_id IS NULL OR p.id = p_user_id)
  GROUP BY p.id, p.full_name;
END;
$$;


