--
-- Name: get_suspicious_access_attempts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_suspicious_access_attempts() RETURNS TABLE(user_id uuid, table_name text, action text, attempt_count bigint, first_attempt timestamp with time zone, last_attempt timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    sal.user_id,
    sal.table_name,
    sal.action,
    COUNT(*)::BIGINT as attempt_count,
    MIN(sal.accessed_at) as first_attempt,
    MAX(sal.accessed_at) as last_attempt
  FROM public.sensitive_data_access_log sal
  WHERE sal.accessed_at > NOW() - INTERVAL '1 hour'
    AND sal.action LIKE '%_attempt'
    AND has_role(auth.uid(), 'admin'::app_role)
  GROUP BY sal.user_id, sal.table_name, sal.action
  HAVING COUNT(*) > 10
  ORDER BY attempt_count DESC;
$$;


--
-- Name: get_territory_sales_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_territory_sales_summary(territory_id_param uuid, start_date_param date DEFAULT (CURRENT_DATE - '30 days'::interval), end_date_param date DEFAULT CURRENT_DATE) RETURNS TABLE(total_sales numeric, total_orders bigint, total_retailers bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT 
    COALESCE(SUM(o.total_amount), 0) as total_sales,
    COUNT(DISTINCT o.id) as total_orders,
    COUNT(DISTINCT r.id) as total_retailers
  FROM territories t
  LEFT JOIN retailers r ON r.id IN (
    SELECT id FROM retailers 
    WHERE EXISTS (
      SELECT 1 FROM unnest(t.pincode_ranges) AS pincode
      WHERE retailers.address LIKE '%' || pincode || '%'
    )
  )
  LEFT JOIN orders o ON o.retailer_id = r.id 
    AND o.created_at::date BETWEEN start_date_param AND end_date_param
  WHERE t.id = territory_id_param
  GROUP BY t.id;
$$;


