--
-- Name: update_leave_balance_on_approval(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_leave_balance_on_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    leave_days INTEGER;
BEGIN
    -- Only update balance when status changes to approved
    IF NEW.status = 'approved' AND OLD.status != 'approved' THEN
        -- Calculate number of leave days
        leave_days := NEW.end_date - NEW.start_date + 1;
        
        -- Update or insert leave balance
        INSERT INTO public.leave_balance (user_id, leave_type_id, used_balance)
        VALUES (NEW.user_id, NEW.leave_type_id, leave_days)
        ON CONFLICT (user_id, leave_type_id, year)
        DO UPDATE SET 
            used_balance = public.leave_balance.used_balance + leave_days,
            updated_at = now();
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: update_new_retailer_actual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_new_retailer_actual() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.user_period_targets upt
  SET 
    actual_value = public.calculate_new_retailers(NEW.user_id, upt.period_start, upt.period_end),
    achievement_percent = CASE 
      WHEN target_value > 0 THEN ROUND((actual_value / target_value) * 100, 2) 
      ELSE 0 
    END,
    last_calculated_at = now()
  WHERE upt.user_id = NEW.user_id
    AND upt.kpi_id = (SELECT id FROM public.target_kpi_definitions WHERE kpi_key = 'new_retailer_addition')
    AND NEW.created_at::DATE BETWEEN upt.period_start AND upt.period_end;
  RETURN NEW;
END;
$$;


