--
-- Name: update_revenue_actual(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_revenue_actual() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('confirmed', 'delivered') THEN
    UPDATE public.user_period_targets upt
    SET 
      actual_value = public.calculate_revenue_contribution(NEW.user_id, upt.period_start, upt.period_end),
      achievement_percent = CASE 
        WHEN target_value > 0 THEN ROUND((actual_value / target_value) * 100, 2) 
        ELSE 0 
      END,
      last_calculated_at = now()
    WHERE upt.user_id = NEW.user_id
      AND upt.kpi_id = (SELECT id FROM public.target_kpi_definitions WHERE kpi_key = 'revenue_contribution')
      AND NEW.order_date BETWEEN upt.period_start AND upt.period_end;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: update_security_info(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_security_info(new_hint_question text, new_hint_answer text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only allow users to update their own security info
  UPDATE public.profiles 
  SET 
    hint_question = new_hint_question,
    hint_answer = new_hint_answer,
    updated_at = now()
  WHERE id = auth.uid();
  
  RETURN FOUND;
END;
$$;


--
-- Name: update_security_info_secure(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_security_info_secure(new_hint_question text, new_hint_answer text, new_recovery_email text DEFAULT NULL::text, new_phone_number text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Only allow users to update their own security info
  UPDATE public.profiles 
  SET 
    hint_question = new_hint_question,
    hint_answer = public.hash_hint_answer(new_hint_answer),
    recovery_email = COALESCE(new_recovery_email, recovery_email),
    phone_number = COALESCE(new_phone_number, phone_number),
    updated_at = now()
  WHERE id = auth.uid();
  
  RETURN FOUND;
END;
$$;


--
-- Name: update_sensitive_profile_fields(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_sensitive_profile_fields(new_phone_number text DEFAULT NULL::text, new_recovery_email text DEFAULT NULL::text, new_hint_question text DEFAULT NULL::text, new_hint_answer text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  hashed_answer text;
BEGIN
  -- Hash the hint answer if provided
  IF new_hint_answer IS NOT NULL THEN
    hashed_answer := public.hash_hint_answer(new_hint_answer);
  END IF;
  
  -- Update only the fields that were provided and belong to the authenticated user
  UPDATE public.profiles 
  SET 
    phone_number = COALESCE(new_phone_number, phone_number),
    recovery_email = COALESCE(new_recovery_email, recovery_email),
    hint_question = COALESCE(new_hint_question, hint_question),
    hint_answer = COALESCE(hashed_answer, hint_answer),
    updated_at = now()
  WHERE id = auth.uid();
  
  RETURN FOUND;
END;
$$;


