--
-- Name: productive_summary_daywise; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.productive_summary_daywise WITH (security_invoker='true') AS
 SELECT to_char((planned_date)::timestamp with time zone, 'FMMonth DD, YYYY'::text) AS planned_date,
    count(
        CASE
            WHEN (status = 'productive'::text) THEN 1
            ELSE NULL::integer
        END) AS productive_visits,
    count(
        CASE
            WHEN (status = 'unproductive'::text) THEN 1
            ELSE NULL::integer
        END) AS unproductive_visits,
    count(id) AS total_visits,
    round((((count(
        CASE
            WHEN (status = 'productive'::text) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(id), 0))::numeric) * (100)::numeric), 2) AS productivity_percentage
   FROM public.visits v
  WHERE ((status = ANY (ARRAY['productive'::text, 'unproductive'::text])) AND (planned_date >= ((CURRENT_DATE - '30 days'::interval))::date))
  GROUP BY planned_date
  ORDER BY v.planned_date DESC;


--
-- Name: productive_summary_week; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.productive_summary_week WITH (security_invoker='true') AS
 SELECT to_char((planned_date)::timestamp with time zone, 'FMMonth DD, YYYY'::text) AS planned_date,
    count(
        CASE
            WHEN (status = 'productive'::text) THEN 1
            ELSE NULL::integer
        END) AS productive_visits,
    count(
        CASE
            WHEN (status = 'unproductive'::text) THEN 1
            ELSE NULL::integer
        END) AS unproductive_visits,
    count(id) AS total_visits,
    round((((count(
        CASE
            WHEN (status = 'productive'::text) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(id), 0))::numeric) * (100)::numeric), 2) AS productivity_percentage
   FROM public.visits v
  WHERE ((status = ANY (ARRAY['productive'::text, 'unproductive'::text])) AND (planned_date >= ((CURRENT_DATE - '7 days'::interval))::date))
  GROUP BY planned_date
  ORDER BY v.planned_date DESC;


