    hint_answer text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    user_status public.user_status DEFAULT 'active'::public.user_status,
    invitation_token text,
    profile_picture_url text,
    date_of_birth date,
    anniversary_date date,
    permanent_address text,
    current_address text,
    emergency_contact_name text,
    emergency_contact_phone text,
    linkedin_url text,
    facebook_url text,
    instagram_url text,
    interests text[],
    aspirations text,
    learning_goals text[],
    work_location text,
    territories_covered text[],
    role_id uuid,
    onboarding_completed boolean DEFAULT false,
    onboarding_step integer DEFAULT 0,
    preferred_language character varying(5) DEFAULT 'en'::character varying,
    tenant_id uuid,
    CONSTRAINT profiles_full_name_not_empty CHECK ((length(TRIM(BOTH FROM full_name)) > 0)),
    CONSTRAINT profiles_hint_answer_not_empty CHECK ((length(TRIM(BOTH FROM hint_answer)) > 0)),
    CONSTRAINT profiles_hint_question_not_empty CHECK ((length(TRIM(BOTH FROM hint_question)) > 0)),
    CONSTRAINT profiles_username_not_empty CHECK ((length(TRIM(BOTH FROM username)) > 0))
);


--
-- Name: TABLE profiles; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.profiles IS 'User profiles with RLS enabled. Users can only access their own data, admins can access all for management purposes.';


--
-- Name: COLUMN profiles.preferred_language; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profiles.preferred_language IS 'User preferred language code (en, hi, kn, ta, te)';


--
-- Name: productive_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.productive_view WITH (security_invoker='true') AS
 SELECT p.full_name,
    count(
        CASE
            WHEN (v.status = 'productive'::text) THEN 1
            ELSE NULL::integer
        END) AS productive_visits,
    count(v.id) AS total_visits,
    round((((count(
        CASE
            WHEN (v.status = 'productive'::text) THEN 1
            ELSE NULL::integer
        END))::numeric / (NULLIF(count(v.id), 0))::numeric) * (100)::numeric), 2) AS productivity_percentage
   FROM (public.visits v
     LEFT JOIN public.profiles p ON ((v.user_id = p.id)))
  WHERE ((v.status = ANY (ARRAY['productive'::text, 'unproductive'::text])) AND (v.planned_date >= ((CURRENT_DATE - '30 days'::interval))::date))
  GROUP BY p.full_name;


